+#ifdef WIN32
+static gboolean
+is_drive_root (const char *path)
+{
+    if (!path)
+        return FALSE;
+
+    if (!g_ascii_isalpha (path[0]) || path[1] != ':')
+        return FALSE;
+
+    const char *p = path + 2;
+    while (*p != '\0') {
+        if (!is_separator (*p))
+            return FALSE;
+        p++;
+    }
+
+    return TRUE;
+}
+#endif
